import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.D8Tso2Ul.js";const h=JSON.parse('{"title":"Módulo: Personas","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/personas.md","filePath":"modulos/personas.md"}'),o={name:"modulos/personas.md"};function r(d,a,i,l,p,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="modulo-personas" tabindex="-1">Módulo: Personas <a class="header-anchor" href="#modulo-personas" aria-label="Permalink to &quot;Módulo: Personas&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/</code> · <code>Backend/handlers/personas-module/</code> · <code>lib/models/Persona</code></p><p>La entidad <strong>Persona</strong> unifica en un solo registro lo que antes eran dos tablas separadas (Users y Workers). Toda persona del sistema —admin, prevencionista, supervisor, jefe de obra o trabajador— es un único registro con un único <code>personaId</code>.</p><h2 id="por-que-identidad-unificada" tabindex="-1">Por qué identidad unificada <a class="header-anchor" href="#por-que-identidad-unificada" aria-label="Permalink to &quot;Por qué identidad unificada&quot;">​</a></h2><p>Antes existían <code>userId</code> (acceso web) y <code>workerId</code> (trabajador en terreno) por separado, lo que obligaba a sincronizar manualmente y duplicaba el hash del PIN. La unificación resuelve esto:</p><ul><li><strong>Un solo ID</strong> (<code>personaId</code>).</li><li><strong>Un solo hash de PIN</strong> (<code>pinHash</code>), generado una vez.</li><li>Sin sincronización manual entre tablas.</li></ul><h2 id="estructura" tabindex="-1">Estructura <a class="header-anchor" href="#estructura" aria-label="Permalink to &quot;Estructura&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>personaId        UUID (reemplaza userId y workerId)</span></span>
<span class="line"><span>tenantId         FK al tenant</span></span>
<span class="line"><span>rut              RUT chileno formateado</span></span>
<span class="line"><span>nombre / apellido / email / telefono</span></span>
<span class="line"><span>rol              admin | prevencionista | supervisor | trabajador</span></span>
<span class="line"><span>permisos         Derivados del rol</span></span>
<span class="line"><span>cargo            Cargo laboral</span></span>
<span class="line"><span>obraIds          Lista de obras asignadas</span></span>
<span class="line"><span>tieneAccesoWeb   BOOL — si puede hacer login en la plataforma</span></span>
<span class="line"><span>passwordHash     Solo si tieneAccesoWeb = true</span></span>
<span class="line"><span>pinHash          Hash del PIN para firma digital</span></span>
<span class="line"><span>pinCreatedAt     Timestamp</span></span>
<span class="line"><span>habilitado       true cuando completó enrolamiento</span></span>
<span class="line"><span>firmaEnrolamiento  Datos de la firma de enrolamiento</span></span>
<span class="line"><span>estado           pendiente | activo | inactivo</span></span></code></pre></div><h2 id="acceso-web-vs-firma-en-terreno" tabindex="-1">Acceso web vs. firma en terreno <a class="header-anchor" href="#acceso-web-vs-firma-en-terreno" aria-label="Permalink to &quot;Acceso web vs. firma en terreno&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Caso</th><th><code>tieneAccesoWeb</code></th><th><code>passwordHash</code></th><th><code>pinHash</code></th></tr></thead><tbody><tr><td>Admin / Prevencionista</td><td><code>true</code></td><td>✅</td><td>✅</td></tr><tr><td>Trabajador con app</td><td><code>true</code></td><td>✅</td><td>✅</td></tr><tr><td>Trabajador solo terreno</td><td><code>false</code></td><td>✗</td><td>✅</td></tr></tbody></table><p>Una persona puede <strong>no tener acceso web</strong> pero sí tener PIN para firmar documentos en terreno. Esto cubre a trabajadores que solo firman desde el dispositivo del supervisor.</p><h2 id="enrolamiento" tabindex="-1">Enrolamiento <a class="header-anchor" href="#enrolamiento" aria-label="Permalink to &quot;Enrolamiento&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Se crea la persona (estado: pendiente)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. La persona completa su firma de enrolamiento (firmaEnrolamiento)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Se activa su PIN (pinHash + pinCreatedAt)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. habilitado = true, estado = activo</span></span></code></pre></div><h2 id="roles-y-permisos" tabindex="-1">Roles y permisos <a class="header-anchor" href="#roles-y-permisos" aria-label="Permalink to &quot;Roles y permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rol</th><th>Alcance</th></tr></thead><tbody><tr><td>admin</td><td>Gestión completa del tenant</td></tr><tr><td>prevencionista</td><td>Crear actividades, asignar documentos, ver reportes</td></tr><tr><td>supervisor</td><td>Firmar como relator, ver trabajadores de su obra</td></tr><tr><td>jefe_obra</td><td>Gestión operativa de la obra</td></tr><tr><td>trabajador</td><td>Ver documentos asignados, firmar, registrar asistencia</td></tr></tbody></table><p>Detalle completo en <a href="/manual/roles/">Roles de Usuario</a>.</p><h2 id="asignacion-a-obras" tabindex="-1">Asignación a obras <a class="header-anchor" href="#asignacion-a-obras" aria-label="Permalink to &quot;Asignación a obras&quot;">​</a></h2><p><code>obraIds</code> es una lista: una persona puede estar asignada a <strong>múltiples obras</strong> simultáneamente. El contexto de obra activa se gestiona en el frontend con <code>ObraContext</code>.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/personas</code></td><td>Crear persona</td></tr><tr><td><code>GET</code></td><td><code>/personas</code></td><td>Listar personas del tenant</td></tr><tr><td><code>GET</code></td><td><code>/personas/{id}</code></td><td>Detalle</td></tr><tr><td><code>PUT</code></td><td><code>/personas/{id}</code></td><td>Actualizar</td></tr><tr><td><code>POST</code></td><td><code>/personas/{id}/change-password</code></td><td>Cambiar contraseña</td></tr></tbody></table><p>Ver detalle en <a href="/manual/api/personas.html">API · Personas</a>.</p>`,21)])])}const b=e(o,[["render",r]]);export{h as __pageData,b as default};
